package com.chaos.mybatis.support;

/**
 * Receives a key generated by the database for an immutable MyBatis statement parameter.
 *
 * <p>Use this holder as a separate mapper parameter when the inserted value cannot accept key
 * mutation, for example a Java record. Configure MyBatis with a nested key property such as
 * {@code key.value}. This type only carries the generated technical key; business fields and
 * business exception translation remain the application's responsibility.
 *
 * @param <T> generated key type returned by the JDBC driver
 */
public final class GeneratedKey<T> {
    private T value;

    /**
     * Returns the generated key, or {@code null} before MyBatis writes it.
     *
     * @return generated key; {@code null} when the insert has not populated it
     */
    public T getValue() {
        return value;
    }

    /**
     * Accepts the key written by MyBatis after a successful insert.
     *
     * @param value key returned by the JDBC driver
     */
    public void setValue(T value) {
        this.value = value;
    }

    /**
     * Returns the generated key and fails fast when the driver did not return one.
     *
     * @return generated key populated by MyBatis
     * @throws IllegalStateException when MyBatis did not populate a generated key
     */
    public T requiredValue() {
        if (value == null) {
            throw new IllegalStateException("Database did not return a generated key");
        }
        return value;
    }
}
